rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels}

def resolve(rid):
    t = relmap[rid]
    if t.startswith('/'):
        return t.lstrip('/')
    if t.startswith('xl/'):
        return t
    return 'xl/' + t

for name, rid in sheets:
    root = ET.fromstring(z.read(resolve(rid)))
    print(f"===== Sheet: {name} =====")
    for row in root.iter(f'{M}row'):
        out = []
        for c in row.findall(f'{M}c'):
            ref = c.get('r'); t = c.get('t')
            v = c.find(f'{M}v')
            val = v.text if v is not None else None
            if t == 's' and val is not None:
                val = shared[int(val)]
            out.append(f"{ref}={val}")
        print(" | ".join(out))
